LOGOS = {
    "jazzy": JAZZY,
    "humble": HUMBLE,
    "iron": IRON,
    "rolling": ROLLING,
    "noetic": NOETIC,
    "kilted": KILTED,
}


def get_logo(distro: str, terminal_width: int = 80) -> str:
    """Return the ANSI art for a distro, scaled to fit terminal width."""
    raw = LOGOS.get(distro.lower(), LOGOS.get("jazzy", ""))
    if not raw:
        return ""
    return _scale_logo(raw, terminal_width)


# ── ANSI-aware regex for stripping escape codes ──────────────────────────
_ANSI_RE = _re.compile(r"\033\[[0-9;]*m")


def _visible_len(s: str) -> int:
    """Length of a string ignoring ANSI escape sequences."""
    return len(_ANSI_RE.sub("", s))


def _scale_logo(logo: str, terminal_width: int) -> str:
    """Scale the logo by sampling logical colored cells, never raw ANSI text."""
    logical_lines = _parse_logo_cells(logo)
    if not logical_lines:
        return logo

    orig_width = max((len(line) for line in logical_lines), default=0)
    if orig_width == 0:
        return logo

    target_width = max(1, min(orig_width, terminal_width or orig_width))
    if target_width >= orig_width:
        return _encode_logo_cells(logical_lines)

    scale = target_width / orig_width
    target_height = max(1, int(len(logical_lines) * scale))
    step_y = len(logical_lines) / target_height
    scaled_lines = []

    for yi in range(target_height):
        source_line = logical_lines[min(int(yi * step_y), len(logical_lines) - 1)]
        if not source_line:
            scaled_lines.append([])
            continue

        target_chars = max(1, int(len(source_line) * scale))
        step_x = len(source_line) / target_chars
        sampled = [
            source_line[min(int(xi * step_x), len(source_line) - 1)]
            for xi in range(target_chars)
        ]
        scaled_lines.append(sampled)

    return _encode_logo_cells(scaled_lines)


def _parse_logo_cells(logo: str) -> list[list[tuple[str, int | None, int | None, int | None]]]:
    """Parse ANSI logo text into visible cells: (char, r, g, b)."""
    lines = [[]]
    current_color: tuple[int, int, int] | None = None
    i = 0

    while i < len(logo):
        ch = logo[i]

        if ch == "\n":
            lines.append([])
            i += 1
            continue

        if ch == "\033":
            match = _ANSI_RE.match(logo, i)
            if match:
                sequence = match.group(0)
                color_match = _re.fullmatch(r"\033\[38;2;(\d+);(\d+);(\d+)m", sequence)
                if color_match:
                    current_color = tuple(int(part) for part in color_match.groups())
                elif sequence == "\033[0m":
                    current_color = None
                i = match.end()
                continue

        if ch == " " or current_color is None:
            lines[-1].append((ch, None, None, None))
        else:
            r, g, b = current_color
            lines[-1].append((ch, r, g, b))
        i += 1

    return lines


def _encode_logo_cells(lines: list[list[tuple[str, int | None, int | None, int | None]]]) -> str:
    """Encode logical cells back into grouped ANSI text."""
    encoded_lines = []

    for line in lines:
        parts = []
        active_color: tuple[int, int, int] | None = None

        for ch, r, g, b in line:
            color = None if r is None or g is None or b is None else (r, g, b)
            if color != active_color:
                if color is None:
                    if active_color is not None:
                        parts.append("\033[0m")
                else:
                    parts.append(f"\033[38;2;{color[0]};{color[1]};{color[2]}m")
                active_color = color
            parts.append(ch)

        if active_color is not None:
            parts.append("\033[0m")
        encoded_lines.append("".join(parts))

    return "\n".join(encoded_lines)
